export const useInvoiceData = () => {
  const [invoiceData, setInvoiceData] = useState<InvoiceData | null>(null);

  // Load from local storage
  useEffect(() => {
    try {
      const stored = localStorage.getItem('tapfolio_invoice_data');
      if (stored) {
        setInvoiceData(JSON.parse(stored));
      } else {
        setInvoiceData(getInitialData());
      }
    } catch (e) {
      console.error('Error loading invoice data from localStorage', e);
      setInvoiceData(getInitialData());
    }
  }, []);

  // Save to local storage
  useEffect(() => {
    if (invoiceData) {
      try {
        localStorage.setItem('tapfolio_invoice_data', JSON.stringify(invoiceData));
      } catch (e) {
        console.error('Error saving invoice data to localStorage', e);
      }
    }
  }, [invoiceData]);

  const updateCompany = (info: Partial<CompanyInfo>) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        company: { ...prev.company, ...info }
      };
    });
  };

  const updateClient = (info: Partial<ClientInfo>) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        client: { ...prev.client, ...info }
      };
    });
  };

  const updateDetails = (info: Partial<InvoiceDetails>) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        details: { ...prev.details, ...info }
      };
    });
  };

  const updatePayment = (info: Partial<PaymentDetails>) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        payment: { ...prev.payment, ...info }
      };
    });
  };

  const updateNotes = (notes: string) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      return { ...prev, notes };
    });
  };

  const updateTerms = (terms: string) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      return { ...prev, terms };
    });
  };

  const updateTemplate = (template: InvoiceData['template']) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      return { ...prev, template };
    });
  };

  const addItem = () => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      const newItem: InvoiceItem = {
        id: Date.now().toString(),
        item: '',
        description: '',
        quantity: 1,
        unitPrice: 0,
        taxPercent: 0,
        discount: 0
      };
      return {
        ...prev,
        items: [...prev.items, newItem]
      };
    });
  };

  const updateItem = (id: string, updatedItem: Partial<InvoiceItem>) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        items: prev.items.map((item) => {
          if (item.id === id) {
            return { ...item, ...updatedItem };
          }
          return item;
        })
      };
    });
  };

  const removeItem = (id: string) => {
    setInvoiceData((prev) => {
      if (!prev) return prev;
      // Keep at least one item
      if (prev.items.length <= 1) {
        return {
          ...prev,
          items: [
            {
              id: Date.now().toString(),
              item: '',
              description: '',
              quantity: 1,
              unitPrice: 0,
              taxPercent: 0,
              discount: 0
            }
          ]
        };
      }
      return {
        ...prev,
        items: prev.items.filter((item) => item.id !== id)
      };
    });
  };

  const resetToDefault = () => {
    setInvoiceData(getInitialData());
  };

  const clearAll = () => {
    setInvoiceData({
      company: {
        logo: '',
        name: '',
        tagline: '',
        address: '',
        phone: '',
        email: '',
        website: '',
        gstNumber: '',
        panNumber: ''
      },
      client: {
        logo: '',
        name: '',
        company: '',
        address: '',
        email: '',
        phone: '',
        gst: ''
      },
      details: {
        number: '',
        date: '',
        dueDate: '',
        currency: 'USD',
        status: 'Pending',
        discount: 0,
        advancePayment: 0
      },
      items: [
        {
          id: Date.now().toString(),
          item: '',
          description: '',
          quantity: 1,
          unitPrice: 0,
          taxPercent: 0,
          discount: 0
        }
      ],
      payment: {
        bankName: '',
        accountName: '',
        accountNumber: '',
        ifsc: '',
        swift: '',
        upiId: '',
        showQrCode: false
      },
      notes: '',
      terms: '',
      template: 'corporate'
    });
  };

  // Helper calculations
  const calculateTotals = () => {
    if (!invoiceData) {
      return {
        subtotal: 0,
        itemDiscounts: 0,
        globalDiscount: 0,
        tax: 0,
        grandTotal: 0,
        advancePayment: 0,
        balanceDue: 0
      };
    }

    const itemTotals = invoiceData.items.reduce(
      (acc, item) => {
        const itemSubtotal = item.quantity * item.unitPrice;
        const itemDiscount = item.discount;
        const taxableAmount = Math.max(0, itemSubtotal - itemDiscount);
        const itemTax = taxableAmount * (item.taxPercent / 100);

        return {
          subtotal: acc.subtotal + itemSubtotal,
          itemDiscounts: acc.itemDiscounts + itemDiscount,
          tax: acc.tax + itemTax
        };
      },
      { subtotal: 0, itemDiscounts: 0, tax: 0 }
    );

    const subtotal = itemTotals.subtotal;
    const itemDiscounts = itemTotals.itemDiscounts;
    const globalDiscount = invoiceData.details.discount || 0;
    const tax = itemTotals.tax;
    const grandTotal = Math.max(0, subtotal - itemDiscounts - globalDiscount) + tax;
    const advancePayment = invoiceData.details.advancePayment || 0;
    const balanceDue = grandTotal - advancePayment;

    return {
      subtotal,
      itemDiscounts,
      globalDiscount,
      tax,
      grandTotal,
      advancePayment,
      balanceDue
    };
  };

  return {
    invoiceData,
    updateCompany,
    updateClient,
    updateDetails,
    updatePayment,
    updateNotes,
    updateTerms,
    updateTemplate,
    addItem,
    updateItem,
    removeItem,
    resetToDefault,
    clearAll,
    totals: calculateTotals()
  };
};
